codeExample.bad:
/* Fixed-height card with overflow:hidden: at default spacing the bio
   text fits, but once a user's stylesheet applies 1.4.12's spacing
   overrides (line-height, paragraph spacing, letter/word spacing), the
   text grows taller than 120px and the overflow:hidden clips it. */
.author-card {
  height: 120px;
  overflow: hidden;
}
.author-card p {
  margin-bottom: 0;
}

codeExample.good:
/* Flexible sizing: min-height sets a baseline but lets the card grow
   to fit taller text, and there's no overflow:hidden clipping content,
   so the same spacing overrides simply make the card taller instead of
   cutting text off. */
.author-card {
  min-height: 120px;
  overflow: visible;
}
.author-card p {
  margin-bottom: 0;
}
